-- Owner-only prospective parity COMPONENT, not a migration, facade or app grant.
-- Execute only after independent source gate in Root's disposable PG17 UTF8 DB.
-- No Auth, membership, policy, snapshot, physical count or error-closure proof.
BEGIN;
SET LOCAL statement_timeout = '8s';
SET LOCAL lock_timeout = '5s';
SET LOCAL TIME ZONE 'UTC';
CREATE TEMP TABLE count_wire_component_scope (unit_only boolean) ON COMMIT DROP;

CREATE FUNCTION pg_temp.count_wire_keys(v jsonb, wanted text[]) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $keys$
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 RETURN (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(v) k)
   IS NOT DISTINCT FROM (SELECT array_agg(k ORDER BY k COLLATE "C") FROM unnest(wanted) k);
END
$keys$;
CREATE FUNCTION pg_temp.count_wire_uuid(v jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog AS $uuid$
 SELECT jsonb_typeof(v)='string' AND (v#>>'{}')~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 AND (v#>>'{}')<>'00000000-0000-0000-0000-000000000000'
$uuid$;
CREATE FUNCTION pg_temp.count_wire_text(v jsonb, maximum integer, require_nonblank boolean) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog AS $text$
DECLARE s text; cp integer; found_nonblank boolean:=false;
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'string' THEN RETURN false; END IF;
 s:=v#>>'{}'; IF octet_length(s)>maximum THEN RETURN false; END IF;
 FOR cp IN SELECT ascii(c) FROM unnest(string_to_array(s,NULL)) c LOOP
  IF NOT(cp BETWEEN 9 AND 13 OR cp IN(32,133,160,5760,8232,8233,8239,8287,12288,65279) OR cp BETWEEN 8192 AND 8203) THEN found_nonblank:=true; END IF;
 END LOOP;
 RETURN NOT require_nonblank OR found_nonblank;
END
$text$;
CREATE FUNCTION pg_temp.count_wire_time(v jsonb) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path = pg_catalog SET TimeZone = 'UTC' AS $time$
DECLARE s text; parsed timestamptz;
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'string' THEN RETURN false; END IF;
 s:=v#>>'{}';
 IF s!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$' OR left(s,4)='0000' THEN RETURN false; END IF;
 BEGIN parsed:=s::timestamptz; EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN false; END;
 RETURN to_char(parsed,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')=s;
END
$time$;
CREATE FUNCTION pg_temp.count_wire_request(action text, v jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $request$
DECLARE wanted text[]; k text; item jsonb; previous_id text; current_id text; array_name text; maximum integer;
BEGIN
 IF action NOT IN('start','statement','finalize','cancel','recover','read') OR action IS NULL OR octet_length(v::text)>262144 THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 wanted:=ARRAY['schema_version','actor_id','count_id'];
 IF action<>'read' THEN wanted:=wanted||ARRAY['operation_id']; END IF;
 wanted:=wanted||CASE action WHEN 'start' THEN ARRAY['product_id','site_id','actor_b_id'] WHEN 'statement' THEN ARRAY['snapshot_id','statement_id','observed_at','method','quantities','container_checks','findings'] WHEN 'finalize' THEN ARRAY['outcome_id'] WHEN 'cancel' THEN ARRAY['cancellation_id','reason'] ELSE ARRAY[]::text[] END;
 IF NOT pg_temp.count_wire_keys(v,wanted) OR jsonb_typeof(v->'schema_version') IS DISTINCT FROM 'number' OR (v->'schema_version')::text IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 FOREACH k IN ARRAY wanted LOOP
  IF right(k,3)='_id' AND pg_temp.count_wire_uuid(v->k) IS NOT TRUE THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 END LOOP;
 IF action='start' AND v->>'actor_id'=v->>'actor_b_id' THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 IF action='cancel' AND pg_temp.count_wire_text(v->'reason',1024,true) IS NOT TRUE THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 IF action='statement' THEN
  IF v->'method' IS DISTINCT FROM '"manual_count"'::jsonb OR pg_temp.count_wire_time(v->'observed_at') IS NOT TRUE THEN RAISE EXCEPTION 'Invalid count component'; END IF;
  FOREACH array_name IN ARRAY ARRAY['quantities','container_checks','findings'] LOOP
   maximum:=CASE WHEN array_name='findings' THEN 32 ELSE 512 END;
   IF jsonb_typeof(v->array_name) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid count component'; END IF;
   IF jsonb_array_length(v->array_name)>maximum THEN RAISE EXCEPTION 'Invalid count component'; END IF;
   previous_id:=NULL;
   FOR item IN SELECT value FROM jsonb_array_elements(v->array_name) LOOP
    IF array_name='quantities' THEN
     IF NOT pg_temp.count_wire_keys(item,ARRAY['cell_id','quantity']) OR pg_temp.count_wire_uuid(item->'cell_id') IS NOT TRUE OR jsonb_typeof(item->'quantity') IS DISTINCT FROM 'string' OR (item->>'quantity')!~'^(0|[1-9][0-9]{0,10})\.[0-9]{3}$' THEN RAISE EXCEPTION 'Invalid count component'; END IF;
     current_id:=item->>'cell_id';
    ELSIF array_name='container_checks' THEN
     IF NOT pg_temp.count_wire_keys(item,ARRAY['container_id','presence']) OR pg_temp.count_wire_uuid(item->'container_id') IS NOT TRUE OR item->'presence' NOT IN('"present"'::jsonb,'"missing"'::jsonb) THEN RAISE EXCEPTION 'Invalid count component'; END IF;
     current_id:=item->>'container_id';
    ELSE
     IF NOT pg_temp.count_wire_keys(item,ARRAY['description','location_id']) OR pg_temp.count_wire_uuid(item->'location_id') IS NOT TRUE OR pg_temp.count_wire_text(item->'description',512,true) IS NOT TRUE THEN RAISE EXCEPTION 'Invalid count component'; END IF;
    END IF;
    IF array_name<>'findings' THEN
     IF previous_id IS NOT NULL AND (current_id COLLATE "C")<=(previous_id COLLATE "C") THEN RAISE EXCEPTION 'Invalid count component'; END IF;
     previous_id:=current_id;
    END IF;
   END LOOP;
  END LOOP;
 END IF;
 RETURN v;
END
$request$;
CREATE FUNCTION pg_temp.count_wire_frame(v jsonb, depth integer DEFAULT 0) RETURNS bytea
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $frame$
DECLARE kind text; result bytea; s text; item jsonb; member record; n integer;
BEGIN
 IF v IS NULL OR depth>6 OR depth<0 OR octet_length(v::text)>262144 THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 kind:=jsonb_typeof(v);
 CASE kind
 WHEN 'null' THEN RETURN convert_to('n','UTF8');
 WHEN 'boolean' THEN RETURN convert_to(CASE WHEN v='true'::jsonb THEN 't' ELSE 'f' END,'UTF8');
 WHEN 'number' THEN IF v::text<>'1' THEN RAISE EXCEPTION 'Invalid count component'; END IF; RETURN decode('69313b','hex');
 WHEN 'string' THEN s:=v#>>'{}'; RETURN convert_to('s'||octet_length(s)::text||':','UTF8')||convert_to(s,'UTF8');
 WHEN 'array' THEN
  n:=jsonb_array_length(v); IF n>512 THEN RAISE EXCEPTION 'Invalid count component'; END IF;
  result:=convert_to('a'||n::text||':','UTF8');
  FOR item IN SELECT value FROM jsonb_array_elements(v) LOOP result:=result||pg_temp.count_wire_frame(item,depth+1); END LOOP;
 WHEN 'object' THEN
  SELECT count(*) INTO n FROM jsonb_object_keys(v); IF n>16 THEN RAISE EXCEPTION 'Invalid count component'; END IF;
  result:=convert_to('o'||n::text||':','UTF8');
  FOR member IN SELECT key,value FROM jsonb_each(v) ORDER BY key COLLATE "C" LOOP
   IF member.key!~'^[a-z_]+$' THEN RAISE EXCEPTION 'Invalid count component'; END IF;
   result:=result||pg_temp.count_wire_frame(to_jsonb(member.key),depth+1)||pg_temp.count_wire_frame(member.value,depth+1);
  END LOOP;
 ELSE RAISE EXCEPTION 'Invalid count component';
 END CASE;
 IF octet_length(result)>524288 THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 RETURN result;
END
$frame$;
CREATE FUNCTION pg_temp.count_wire_request_digest(action text, v jsonb) RETURNS text
LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp AS $digest$
 SELECT encode(sha256(convert_to('lrv-controlled-count-request-v1','UTF8')||decode('00','hex')||pg_temp.count_wire_frame(jsonb_build_object('action',action,'request',pg_temp.count_wire_request(action,v)))),'hex')
$digest$;
CREATE FUNCTION pg_temp.count_wire_receipt(v jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $receipt$
DECLARE k text; wanted_kind text;
BEGIN
 IF octet_length(v::text)>4096 OR NOT pg_temp.count_wire_keys(v,ARRAY['schema_version','action','operation_id','count_id','actor_id','request_digest','result_ref','receipt_digest']) OR jsonb_typeof(v->'schema_version') IS DISTINCT FROM 'number' OR (v->'schema_version')::text IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 wanted_kind:=CASE v->>'action' WHEN 'start' THEN 'cycle' WHEN 'statement' THEN 'statement' WHEN 'finalize' THEN 'outcome' WHEN 'cancel' THEN 'cancellation' END;
 IF wanted_kind IS NULL OR jsonb_typeof(v->'action') IS DISTINCT FROM 'string' OR NOT pg_temp.count_wire_keys(v->'result_ref',ARRAY['kind','id','opaque_commitment']) OR v#>'{result_ref,kind}' IS DISTINCT FROM to_jsonb(wanted_kind) THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 FOREACH k IN ARRAY ARRAY['actor_id','operation_id','count_id'] LOOP IF pg_temp.count_wire_uuid(v->k) IS NOT TRUE THEN RAISE EXCEPTION 'Invalid count component'; END IF; END LOOP;
 IF pg_temp.count_wire_uuid(v#>'{result_ref,id}') IS NOT TRUE THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 FOREACH k IN ARRAY ARRAY['request_digest','receipt_digest'] LOOP IF jsonb_typeof(v->k) IS DISTINCT FROM 'string' OR (v->>k)!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Invalid count component'; END IF; END LOOP;
 IF jsonb_typeof(v#>'{result_ref,opaque_commitment}') IS DISTINCT FROM 'string' OR (v#>>'{result_ref,opaque_commitment}')!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Invalid count component'; END IF;
 RETURN v;
END
$receipt$;
CREATE FUNCTION pg_temp.count_wire_receipt_digest(v jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $receipt_digest$
 SELECT encode(sha256(convert_to('lrv-controlled-count-public-receipt-v1','UTF8')||decode('00','hex')||pg_temp.count_wire_frame(pg_temp.count_wire_receipt(v)-'receipt_digest')),'hex')
$receipt_digest$;
REVOKE ALL ON FUNCTION pg_temp.count_wire_keys(jsonb,text[]), pg_temp.count_wire_uuid(jsonb), pg_temp.count_wire_text(jsonb,integer,boolean), pg_temp.count_wire_time(jsonb), pg_temp.count_wire_request(text,jsonb), pg_temp.count_wire_frame(jsonb,integer), pg_temp.count_wire_request_digest(text,jsonb), pg_temp.count_wire_receipt(jsonb), pg_temp.count_wire_receipt_digest(jsonb) FROM PUBLIC;

